# >>> STATIC
_static_input_format() {
    cat <<-'ARGCEOF'
	text	
	stream-json	realtime streaming input
ARGCEOF
}

_static_output_format() {
    cat <<-'ARGCEOF'
	text	
	json	single result
	stream-json	realtime streaming
ARGCEOF
}

_static_permission_prompts() {
    cat <<-'ARGCEOF'
	host	the SDK host or --permission-prompt-tool
	none	nobody: anything that would prompt is denied automatically; the permission mode still decides everything else
ARGCEOF
}

_static_plugin_eval_mocks() {
    cat <<-'ARGCEOF'
	record	a plugin server with no mock is NOT started (see --allow-real-servers)
	off	no stand-ins, every real server starts (as you, outside the OS sandbox), its tools gated by --allow-tools
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_agent_session() {
    claude agents --json 2>/dev/null | jq -b -r '
        .[]?
        | (.id // .sessionId // .session_id // .shortId) as $id
        | select($id != null)
        | "\($id)\t\(.name // .title // .displayName // "")"
    ' 2>/dev/null
}

_choice_autocompact() {
    echo auto
}

_choice_marketplace() {
    _argc_util_cache 30 _helper_marketplaces claude-marketplaces
}

_choice_mcp_name() {
    local config="$HOME/.claude.json"
    if [[ -f $config ]]; then
        jq -b -r --arg cwd "$PWD" '
            ((.mcpServers // {}) + (.projects[$cwd].mcpServers // {})) | keys[]
        ' "$config" 2>/dev/null
    fi
    if [[ -f .mcp.json ]]; then
        jq -b -r '(.mcpServers // {}) | keys[]' .mcp.json 2>/dev/null
    fi
}

_choice_plugin() {
    _argc_util_cache 30 _helper_installed_plugins claude-installed-plugins
}

_choice_plugin_available() {
    _argc_util_cache 30 _helper_available_plugins claude-available-plugins
}

_choice_session() {
    _choice_agent_session
    local dir="${CLAUDE_CONFIG_DIR:-$HOME/.claude}/projects"
    if [[ -d $dir ]]; then
        find "$dir" -mindepth 2 -maxdepth 2 -type f -name '*.jsonl' 2>/dev/null |
            sed -e 's|.*/||' -e 's|\.jsonl$||' |
            head -n 200
    fi
}

_helper_available_plugins() {
    claude plugin list --available --json 2>/dev/null | jq -b -r '
        (.available // [])[]?
        | (.pluginId // .id) as $id
        | select($id != null)
        | "\($id)\t\(.description // "")"
    ' 2>/dev/null
}

_helper_installed_plugins() {
    claude plugin list --json 2>/dev/null | jq -b -r '
        .[]?
        | select(.id != null)
        | "\(.id)\t\([.scope, .version] | map(select(. != null and . != "")) | join(" "))"
    ' 2>/dev/null
}

_helper_marketplaces() {
    claude plugin marketplace list --json 2>/dev/null | jq -b -r '
        .[]?
        | (.name // .marketplaceName // .id) as $name
        | select($name != null)
        | $name
    ' 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
